def uc_model_version_tag_from_mlflow_tags(
    tags: list[ModelVersionTag] | None,
) -> list[ProtoModelVersionTag]:
    """Convert MLflow ModelVersionTag objects to Unity Catalog protobuf tag objects."""
    if tags is None:
        return []
    return [ProtoModelVersionTag(key=tag.key, value=tag.value) for tag in tags]


